use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

pub fn assess_battery(value: Drone_Lifecycle_Governor::Battery_Sample) -> Drone_Lifecycle_Governor::Battery_Evidence
{
  if (value.status == Drone_Lifecycle_Governor::Input_Status::Invalid) {
    Drone_Lifecycle_Governor::Battery_Evidence::Invalid_Battery
  } else {
    if (value.indication == Drone_Lifecycle_Governor::Battery_Indication::Adequate) {
      Drone_Lifecycle_Governor::Battery_Evidence::Adequate_Battery
    } else {
      Drone_Lifecycle_Governor::Battery_Evidence::Low_Battery
    }
  }
}

/** Initialize EntryPointContract
  *
  * guarantee INITIAL_BATTERY_INVALID
  *   Battery assessment starts in an explicitly untrusted state
  * @param api_battery_evidence_for_governor outgoing data port
  * @param api_battery_evidence_for_notice outgoing data port
  */
pub fn initialize_INITIAL_BATTERY_INVALID(
  api_battery_evidence_for_governor: Drone_Lifecycle_Governor::Battery_Evidence,
  api_battery_evidence_for_notice: Drone_Lifecycle_Governor::Battery_Evidence) -> bool
{
  (api_battery_evidence_for_governor == Drone_Lifecycle_Governor::Battery_Evidence::Invalid_Battery) &
    (api_battery_evidence_for_notice == Drone_Lifecycle_Governor::Battery_Evidence::Invalid_Battery)
}

/** IEP-Guar: Initialize Entrypoint for battery_evidence_assessment
  *
  * @param api_battery_evidence_for_governor outgoing data port
  * @param api_battery_evidence_for_notice outgoing data port
  */
pub fn initialize_IEP_Guar(
  api_battery_evidence_for_governor: Drone_Lifecycle_Governor::Battery_Evidence,
  api_battery_evidence_for_notice: Drone_Lifecycle_Governor::Battery_Evidence) -> bool
{
  initialize_INITIAL_BATTERY_INVALID(api_battery_evidence_for_governor, api_battery_evidence_for_notice)
}

/** IEP-Post: Initialize Entrypoint Post-Condition
  *
  * @param api_battery_evidence_for_governor outgoing data port
  * @param api_battery_evidence_for_notice outgoing data port
  */
pub fn initialize_IEP_Post(
  api_battery_evidence_for_governor: Drone_Lifecycle_Governor::Battery_Evidence,
  api_battery_evidence_for_notice: Drone_Lifecycle_Governor::Battery_Evidence) -> bool
{
  initialize_IEP_Guar(api_battery_evidence_for_governor, api_battery_evidence_for_notice)
}

/** Compute Entrypoint Contract
  *
  * guarantee BATTERY_ASSESSMENT_TOTAL
  *   Both battery fields determine one assessment supplied to both distinct consumers
  * @param api_battery_sample incoming data port
  * @param api_battery_evidence_for_governor outgoing data port
  * @param api_battery_evidence_for_notice outgoing data port
  */
pub fn compute_spec_BATTERY_ASSESSMENT_TOTAL_guarantee(
  api_battery_sample: Drone_Lifecycle_Governor::Battery_Sample,
  api_battery_evidence_for_governor: Drone_Lifecycle_Governor::Battery_Evidence,
  api_battery_evidence_for_notice: Drone_Lifecycle_Governor::Battery_Evidence) -> bool
{
  (api_battery_evidence_for_governor == assess_battery(api_battery_sample)) &
    (api_battery_evidence_for_notice == assess_battery(api_battery_sample))
}

